#[allow(dead_code)]
pub struct RustTreeWalker;

#[allow(dead_code)]
impl RustTreeWalker {
    pub fn walk<E, T: RustListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree, None)
    }

    pub fn walk_with_invocation_states<E, T: RustListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        parent_invocation_states: Vec<isize>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree, Some(parent_invocation_states))
    }

    fn __walk<E, T: RustListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        invocation_states: Option<Vec<isize>>,
    ) -> Result<(), E> {
        let mut callbacks = __RustTreeWalkerCallbacks(listener);
        antlr4_runtime::generated::walk_generated(tree, invocation_states, &mut callbacks)
    }
}

pub type ParseTreeWalker = RustTreeWalker;

